<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';
try{$uid=(int)requireAuth()->id;$delivery=(int)($_GET['delivery_note_id']??0);if($delivery<1)throw new Exception('Delivery note is required');$c=db();requireAnyPermission($c,$uid,['invoices.view','deliveries.view']);$s=$c->prepare("SELECT ii.invoice_id,ii.product_id,ii.product_code,ii.product,ii.qty FROM erp_invoice_items ii JOIN erp_invoices i ON i.id=ii.invoice_id WHERE i.user_id=? AND i.delivery_note_id=? AND UPPER(i.invoice_type)='FACTURE'");$s->bind_param('ii',$uid,$delivery);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();jsonResponse(['success'=>true,'data'=>$rows]);}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>'Could not load linked invoice items.','error_code'=>'DELIVERY_INVOICE_ITEMS_FAILED'],400);}
